// src/services/style-preset.ts
var STYLE_BODY_SEP = "---BODY-RENDER-LANGUAGE---";
var STYLE_BODY_SEP_EN = "---BODY-RENDER-LANGUAGE-EN---";
async function loadPresetPrompt(dramaId) {
  if (!dramaId) return "";
  const [drama] = await db.select().from(schema_exports.dramas).where(eq(schema_exports.dramas.id, dramaId));
  if (!drama?.style) return "";
  const [preset] = await db.select().from(schema_exports.stylePresets).where(and(eq(schema_exports.stylePresets.value, drama.style), eq(schema_exports.stylePresets.isActive, true)));
  return preset?.prompt || "";
}
async function getDramaStylePrompt(dramaId) {
  return (await getDramaStyleSpec(dramaId)).head;
}
async function getDramaStyleSpec(dramaId) {
  const raw = await loadPresetPrompt(dramaId);
  if (!raw) return { head: "", bodyRules: "", bodyRulesEn: "" };
  const idx = raw.indexOf(STYLE_BODY_SEP);
  if (idx < 0) return { head: raw.trim(), bodyRules: "", bodyRulesEn: "" };
  const head = raw.slice(0, idx).trim();
  let body = raw.slice(idx + STYLE_BODY_SEP.length).trim();
  let bodyRulesEn = "";
  const enIdx = body.indexOf(STYLE_BODY_SEP_EN);
  if (enIdx >= 0) {
    bodyRulesEn = body.slice(enIdx + STYLE_BODY_SEP_EN.length).trim();
    body = body.slice(0, enIdx).trim();
  }
  return { head, bodyRules: body, bodyRulesEn };
}

