    const name29 = voiceCardName(id);
    if (!fs6.existsSync(refmodCardPath(name29))) return { has_voice_card: false, voice_desc: "" };
    let desc2 = "";
    try {
      desc2 = String(JSON.parse(fs6.readFileSync(voiceMetaPath(name29), "utf8"))?.desc || "");
    } catch {
    }
