import fs8 from "node:fs";
async function buildMediaRefs(storyboardId, slotLimit = 9) {
  const [sb] = await db.select().from(schema_exports.storyboards).where(eq(schema_exports.storyboards.id, storyboardId));
  const refs = [];
  if (!sb) return { refs, slotLimit };
  const charLinks = await db.select().from(schema_exports.storyboardCharacters).where(eq(schema_exports.storyboardCharacters.storyboardId, storyboardId));
  const propLinks = await db.select().from(schema_exports.storyboardProps).where(eq(schema_exports.storyboardProps.storyboardId, storyboardId));
  const allChars = await db.select().from(schema_exports.characters);
  const allProps = await db.select().from(schema_exports.props);
  const allScenes = await db.select().from(schema_exports.scenes);
  let picNo = 1;
  const scene = sb.sceneId ? allScenes.find((s) => s.id === sb.sceneId && !s.deletedAt) : void 0;
  if (scene) {
    refs.push({
      picture: picNo++,
      kind: "scene",
      id: scene.id,
      name: scene.location || "",
      hasImage: !!(scene.imageUrl || "").trim(),
      hasCard: fs8.existsSync(refmodCardPath(refmodCardName("scene", scene.id)))
    });
  }
  for (const cid of charLinks.map((l) => l.characterId).sort((a, b) => a - b)) {
    const ch = allChars.find((x2) => x2.id === cid && !x2.deletedAt);
    if (!ch) continue;
    refs.push({
      picture: picNo++,
      kind: "character",
      id: ch.id,
      name: ch.name,
      // 发色/服装颜色闸的判据：只有「卡里的文字」能被写提示词的模型看到（2026-10-15 加）
      assetText: [ch.appearance, ch.styling, ch.costumeLabel].filter(Boolean).join(" \uFF5C "),
      hasImage: !!(ch.imageUrl || "").trim(),
      hasCard: fs8.existsSync(refmodCardPath(refmodCardName("character", ch.id))),
      // 判据是**源 wav 在不在**（.safetensors 声音卡 2026-10-11 已废）；换装变体沿用原角色时解析到原角色那份
      hasVoiceCard: fs8.existsSync(voiceWavPath(voiceCardName(effectiveVoiceId(ch.id))))
    });
  }
  for (const pid of propLinks.map((l) => l.propId).sort((a, b) => a - b)) {
    const pr = allProps.find((x2) => x2.id === pid && !x2.deletedAt);
    if (!pr) continue;
    refs.push({
      picture: picNo++,
      kind: "prop",
      id: pr.id,
      name: pr.name,
      // 只扫人工写的「描述」；`finalPrompt` 是生成的图片提示词，里面全是「…不再出现任何文字、图标或数字」这类排他句（2026-10-15 误报后去掉）
      assetText: pr.description || "",
      hasImage: !!(pr.imageUrl || "").trim(),
      hasCard: fs8.existsSync(refmodCardPath(refmodCardName("prop", pr.id)))
    });
  }
  return { refs, slotLimit };
}

